{
  "data": {
    "type": "lead",
    "attributes": {

      // ============================================================
      // IDENTIFICAÇÃO DO CLIENTE (Customer)
      // ============================================================

      // Nome do cliente.
      // Default: "Não identificado"
      "name": "Pedro Silva",

      // Email do cliente.
      // Utilizado para deduplicação.
      // Remove "." antes do @ automaticamente.
      "email": "pedro@teste.com",

      // Telefone principal.
      // Se vazio, usa "customer_number" como fallback.
      "phone": "+55 11 99999-9999",

      // Telefone secundário (opcional).
      "phone2": "+55 11 99999-9999",


      // ============================================================
      // PRODUTO / IMÓVEL / VEÍCULO (Product)
      // ============================================================

      // Descrição principal do item.
      // Exibida no card do lead.
      // Máximo: 250 caracteres.
      "description": "Apartamento 2 quartos no Botafogo",

      // Código do imóvel.
      // Obrigatório para empresas do tipo IMOBILIÁRIA.
      // Valores especiais:
      // "Sem código", "Não localizado", "Nenhum", "ignore"
      "prop_ref": "AP12345",

      // Marca do veículo.
      // Apenas empresas de CARROS ou MOTOS.
      "brand": "Volkswagen",

      // Modelo do veículo.
      // Apenas empresas de CARROS ou MOTOS.
      "model": "Polo",

      // Versão do veículo.
      // Apenas empresas de CARROS ou MOTOS.
      "version": "Comfortline 1.6",

      // Ano do veículo.
      // Se igual ao ano atual, pode virar "Novo".
      "year": 2024,

      // Valor do produto/imóvel/veículo.
      // Aceita:
      // "R$ 250.000,00"
      // "250000"
      // "250000.00"
      "price": "R$ 250.000,00",

      // Cor do veículo.
      // Apenas empresas de CARROS ou MOTOS.
      "color": "Prata",

      // Quilometragem.
      // Se 0 => força vehicle_type = "Novo"
      // Apenas empresas de CARROS ou MOTOS.
      "km": 35000,

      // Placa do veículo.
      // Removida automaticamente da descrição.
      // Apenas empresas de CARROS ou MOTOS.
      "license_plate": "ABC1D23",

      // Texto livre da negociação.
      // Faz parser automático de palavras-chave.
      // Evite usar junto com "type_negotiation".
      "type_negotiation_string": "Apartamento para Aluguel por R$ 1.200,00",

      // Tipo de negociação.
      // Apenas IMOBILIÁRIAS.
      // Exemplos:
      // "Comprar"
      // "Alugar"
      // "Lançamento"
      "type_negotiation": "Comprar",

      // Tipo do veículo.
      // Valores comuns:
      // "Novo"
      // "Usado"
      // Apenas empresas de CARROS ou MOTOS.
      "vehicle_type": "Usado",

      // Cidade do imóvel.
      // Utilizada na distribuição.
      "city": "Campinas",

      // Bairro do imóvel.
      // Utilizado na distribuição.
      "neighbourhood": "Botafogo",


      // ============================================================
      // LEAD
      // ============================================================

      // ID do canal.
      // Valores possíveis:
      // [1,2,3,4,5]
      // Default: 1 (Internet)
      "channel_id": 1,

      // Abreviação do canal.
      // Exemplos:
      // "internet"
      // "whatsapp"
      // "telefone"
      // "showroom"
      "channel_abbrev": "internet",

      // URL do anúncio/origem.
      // Se vazio e existir prop_ref + custom_link,
      // a URL pode ser gerada automaticamente.
      "url": "https://exemplo.com.br/imovel/12345",

      // Campo legado de URL.
      // Alguns parceiros ainda enviam aqui.
      "sourcerUrl": "https://exemplo.com.br/imovel/12345",

      // Primeira mensagem do lead.
      // Máximo: 15.000 caracteres.
      // Aceita HTML.
      "body": "Olá, tenho interesse no imóvel.",

      // Observação interna.
      "observation": "Cliente VIP, retornar com prioridade",

      // ID externo do parceiro.
      // Pode ser usado em distribuições específicas.
      "external_id": "EXT-99887",

      // Sobrescreve o created_at do lead.
      // Timezone da empresa é respeitada.
      "custom_created_at": "2026-05-08T14:30:00",


      // ============================================================
      // ORIGEM / DISTRIBUIÇÃO
      // ============================================================

      // Estado do lead.
      // true  => pendente (distribuível)
      // false => já distribuído ou fechado
      "pending": true,

      // Lead já fechado.
      "closed": false,

      // Já houve interação com o lead.
      "already_interacted": false,

      // Pular na distribuição se já interagido.
      "skip_on_interaction": false,

      // Fonte primária da origem.
      // Exemplos:
      // "portal_zap"
      // "facebook"
      // "google_ads"
      "source": "portal_zap",

      // Palavras-chave para imobiliárias.
      // Exemplos:
      // "aluguel"
      // "venda"
      // "lançamento"
      "real_state_keywords": ["aluguel", "venda"],

      // IDs das tags do lead.
      // Exemplo: ["tag-uuid-1", "tag-uuid-2"]
      "tags": ["tag-uuid-1"],

      // Nome da tag (usado em integrações legadas).
      // Exemplo: "imoveis", "premium"
      "tag_name": "imoveis",


      // ============================================================
      // WHATSAPP / EXTRAS
      // ============================================================

      // Username/número do WhatsApp.
      "wpp_username": "5511903873417",

      // Business Account UID do WhatsApp.
      "bsuid": "1234567890"
    }
  }
}

